head.script:
scwin.gVar = {
    "cStyle" : "",
    "cStyleParent" : "",
}


scwin.onpageload = function () {
    // Global DataList 생성 호출 (dlt_pData 포함)
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof parent1 !== 'undefined') {
        parent1.remove();
    }

    // 조건 설정
    let cStyle = scwin.gVar["cStyle"];
    cStyle += "width:400px; height:300px;"
    let cStyleParent = scwin.gVar["cStyleParent"];


    let properties = {
        style: cStyle,
    };

    let cList = $c.gcm.createCList(properties);

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strParent = '';
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strParent += '<xf:group ' + strNameSpace + ' style="background-color:var(--ws-green-100); height: 400px; '+cStyleParent+'">';
    strParent += '</xf:group>';

    scwin.parent1 = await $p.dynamicCreate(
        "parent1",
        "group",
        strParent,
        grp_comp
    );

    // pivot 은 dlt_pData 바인딩이 필요하므로 직접 dynamicCreate (contextMenuGetter/oncellclick 미정의 함수 제거, position:relative 반영)
    strTarget += '<w2:pivot ' + strNameSpace + ' ' + cList + ' dataList="dlt_pData" showZero="true" rows="col4,col5,col8" bodyTextAlign="right" totalTextAlign="right" cols="col6,col7" vals="col3" aggregatorName="Sum" useNumberFormat="true" digitsAfterDecimal="2" showGrandTotal="true" valuesAxis="row">';
    strTarget += '<w2:fieldInfo>';
    strTarget += '<w2:field id="col1" name="row" sortOrder=""></w2:field>';
    strTarget += '<w2:field id="col2" name="total_bill" sortOrder=""></w2:field>';
    strTarget += '<w2:field id="col3" name="tip" sortOrder=""></w2:field>';
    strTarget += '<w2:field id="col4" name="sex" sortOrder=""></w2:field>';
    strTarget += '<w2:field id="col5" name="smoker" sortOrder=""></w2:field>';
    strTarget += '<w2:field id="col6" name="day" sortOrder=""></w2:field>';
    strTarget += '<w2:field id="col7" name="time" sortOrder=""></w2:field>';
    strTarget += '<w2:field id="col8" name="size" sortOrder=""></w2:field>';
    strTarget += '</w2:fieldInfo>';
    strTarget += '</w2:pivot>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "pivot",
        strTarget,
        parent1
    );
}
